class Placar {
  constructor(casa, visitante) {
    this.casa = casa;
    this.visitante = visitante;
    this.golsCasa = 0;
    this.golsVisitante = 0;
  }

  marcar(time) {
    if (time === this.casa) {
      this.golsCasa += 1;
    } else if (time === this.visitante) {
      this.golsVisitante += 1;
    }
  }

  resultado() {
    return `${this.casa} ${this.golsCasa} x ${this.golsVisitante} ${this.visitante}`;
  }
}

const jogo = new Placar("Tigres", "Leões");
jogo.marcar("Tigres");
jogo.marcar("Leões");
jogo.marcar("Tigres");
jogo.marcar("Panteras");
console.log(jogo.resultado());

