class Heroi {
  #vida;

  constructor(nome, vidaMax) {
    this.nome = nome;
    this.vidaMax = vidaMax;
    this.#vida = vidaMax;
  }

  get vida() {
    return this.#vida;
  }

  set vida(valor) {
    this.#vida = Math.min(this.vidaMax, Math.max(0, valor));
  }

  get estaVivo() {
    return this.#vida > 0;
  }
}

