// A classe Inimigo já está pronta: não mude nada nela.
class Inimigo {
  constructor(nome, vida) {
    this.nome = nome;
    this.vida = vida;
  }

  // aplica o dano (a vida nunca fica negativa) e devolve quanto dano foi aplicado
  receberDano(qtd) {
    const dano = Math.min(this.vida, qtd);
    this.vida -= dano;
    return dano;
  }

  descricao() {
    return `${this.nome} (vida ${this.vida})`;
  }
}

class Chefe extends Inimigo {
  constructor(nome, vida, armadura) {
    super(nome, vida);
    this.armadura = armadura;
  }

  receberDano(qtd) {
    return super.receberDano(Math.max(0, qtd - this.armadura));
  }

  descricao() {
    return `${super.descricao()} [CHEFE]`;
  }
}

