class Carregador {
  constructor() {
    this.carregando = false;
    this.falhas = 0;
  }

  carregar(texto) {
    this.carregando = true;
    try {
      return JSON.parse(texto);
    } catch (erro) {
      this.falhas += 1;
      return null;
    } finally {
      this.carregando = false;
    }
  }
}

const carregador = new Carregador();
console.log(carregador.carregar('{"fase": 4, "moedas": 120}'));
console.log(carregador.carregar("fase 4, 120 moedas"));
console.log(carregador.falhas, carregador.carregando);

