class SaldoInsuficienteError extends Error {
  constructor(falta) {
    super(`Faltam ${falta} moedas`);
    this.name = "SaldoInsuficienteError";
    this.falta = falta;
  }
}

function comprar(saldo, preco) {
  if (preco <= 0) {
    throw new RangeError(`Preço inválido: ${preco}`);
  }
  if (preco > saldo) {
    throw new SaldoInsuficienteError(preco - saldo);
  }
  return saldo - preco;
}

function tentarComprar(saldo, preco) {
  try {
    const novoSaldo = comprar(saldo, preco);
    return `Compra feita. Saldo: ${novoSaldo}`;
  } catch (erro) {
    if (erro instanceof SaldoInsuficienteError) {
      return `Moedas insuficientes: faltam ${erro.falta}`;
    }
    throw erro;
  }
}

