class ForaDeCombateError extends Error {
  constructor(nome) {
    super(`${nome} está fora de combate`);
    this.name = "ForaDeCombateError";
  }
}

class Personagem {
  #vida;

  constructor(nome, vidaMax, ataque) {
    this.nome = nome;
    this.vidaMax = vidaMax;
    this.ataque = ataque;
    this.#vida = vidaMax;
  }

  get vida() {
    return this.#vida;
  }

  get estaVivo() {
    return this.#vida > 0;
  }

  receberDano(qtd) {
    const dano = Math.min(this.#vida, Math.max(0, qtd));
    this.#vida -= dano;
    return dano;
  }

  atacar(alvo) {
    if (!this.estaVivo) {
      throw new ForaDeCombateError(this.nome);
    }
    if (!alvo.estaVivo) {
      throw new ForaDeCombateError(alvo.nome);
    }
    const dano = alvo.receberDano(this.ataque);
    return `${this.nome} ataca ${alvo.nome}: ${dano} de dano`;
  }
}

class Guerreiro extends Personagem {
  constructor(nome, vidaMax, ataque, armadura) {
    super(nome, vidaMax, ataque);
    this.armadura = armadura;
  }

  receberDano(qtd) {
    return super.receberDano(qtd - this.armadura);
  }
}

function executarRodada(acoes) {
  const registro = [];
  for (const [atacante, alvo] of acoes) {
    try {
      registro.push(atacante.atacar(alvo));
    } catch (erro) {
      if (!(erro instanceof ForaDeCombateError)) {
        throw erro;
      }
      registro.push(`Ação cancelada: ${erro.message}`);
    }
  }
  return registro;
}

const ana = new Guerreiro("Ana", 30, 7, 2);
const slime = new Personagem("Slime", 12, 4);
const rodada = executarRodada([[ana, slime], [slime, ana], [ana, slime], [slime, ana]]);
